fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // Compute the split index as half the length (integer division).
    // For len = 0 => mid = 0, returns ([], [])
    // For len = 1 => mid = 0, returns ([], [x])
    // For len = 2 => mid = 1, returns ([x0], [x1])
    // In general, for len > 1, both parts have length < original length.
    let mut first_part = a;
    let mid = first_part.len() / 2;
    let second_part = first_part.split_off(mid);
    (first_part, second_part)
}

